redcap_field_annotation:
 @HIDDEN
@CALCTEXT(
  concat(
    'https://webcdi.org/interface/HBCD/',
    if(
        [webcdi_en_age] < 16 AND [project-id] = 43,
        'WG%20EN%20-%20Sandbox',
        if(
            [webcdi_en_age] < 16 AND [project-id] = 57,
            'WG%20EN',
                if(
                [webcdi_en_age] >= 16 AND [project-id] = 43,
                'WS%20EN%20-%20Sandbox',
                    if(
                    [webcdi_en_age] >= 16 AND [project-id] = 57,
                    'WS%20EN',
                    'ERROR'
                )
            )
        )
    ),
    '/new_parent/?',
    'source_id=', [screening_arm_1][record_id],  '&',
    'event_id=',  [event-name], '&',
    'age=',       [webcdi_en_age], '&',
    'sex=',       [screening_arm_1][setup_sex],  '&',
    'offset=',    [screening_arm_1][setup_offset]
  )
)

